def compute_transient_windows(onset_samples, sr, n_samples):
    """Build merged, non-overlapping [start, end, anchor] windows around
    each onset sample. `anchor` is the original onset sample used to align
    the transient's temporal position in the output.
    """
    pre = int(round(TRANS_PRE_MS / 1000.0 * sr))
    post = int(round(TRANS_POST_MS / 1000.0 * sr))

    windows = []
    for onset in onset_samples:
        start = max(0, int(onset) - pre)
        end = min(n_samples, int(onset) + post)
        if end <= start:
            continue
        windows.append([start, end, int(onset)])

    windows.sort(key=lambda w: w[0])
    merged = []
    for w in windows:
        if merged and w[0] <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], w[1])
            # keep the earliest onset as the representative anchor
        else:
            merged.append(w)
    return merged
